            ]) : $this->db->query('select "uid", "platform_identity", "role", "version" from "access_platform_identity_role" where "platform_identity" = :parent', [
              new SqlParam(name: 'parent', value: $value['uid'], type: SqlParam::STR)
            ]);
            foreach ($childsRoles as $childRoles) {
                $value['roles'][] = new PlatformIdentityRolesItem(
                    uid: PlatformIdentityRolesUidVO::from($childRoles['uid']),
                    role: PlatformIdentityRolesRoleVO::from(new RoleRef($childRoles['role'])),
                    version: PlatformIdentityRolesVersionVO::from($childRoles['version']),
                );
            }
            return $this->mapper($value);
        }
        return $value;
    }
}
